from fractions import Fraction
nums=[3,8,11,19,25,75]
target=Fraction(462)
from functools import lru_cache

def solve(items):
    # items tuple of (value, expr, usedmask) but simpler recursive set
    if len(items)==1:
        if items[0][0]==target:
            print(items[0][1])
            raise SystemExit
        return
    n=len(items)
    for i in range(n):
        for j in range(i+1,n):
            a,ea=items[i]; b,eb=items[j]
            rest=[items[k] for k in range(n) if k not in (i,j)]
            cands=[(a+b,f'({ea} + {eb})'),(a-b,f'({ea} - {eb})'),(b-a,f'({eb} - {ea})'),(a*b,f'({ea} * {eb})')]
            if b: cands.append((a/b,f'({ea} / {eb})'))
            if a: cands.append((b/a,f'({eb} / {ea})'))
            for v,e in cands:
                solve(rest+[(v,e)])

for r in range(1, len(nums)+1):
    import itertools
    for comb in itertools.combinations(nums,r):
        solve([(Fraction(x),str(x)) for x in comb])
